fn find(a: Vec<i32>, key: i32) -> usize {
    let mut idx: usize = 0;
    // Loop until we either find the key or exhaust the array
    while idx < a.len() {
        if a[idx] == key {
            return idx;
        }
        idx += 1;
    }
    // If not found, return a.len()
    idx
}

